

CREATE TABLE "bd_tipopersonal" (
	"id" INTEGER NOT NULL,
	"personal" VARCHAR(300) NULL DEFAULT NULL,
	PRIMARY KEY ("id")
)
;

CREATE TABLE "bd_institucion" (
	"id" INTEGER NOT NULL,
	"institucion" VARCHAR(300) NULL DEFAULT NULL,
	PRIMARY KEY ("id")
)
;

CREATE TABLE "bd_departamento" (
	"id" INTEGER NOT NULL,
	"departamento" VARCHAR(300) NULL DEFAULT NULL,
	"id_institucion" INTEGER NULL DEFAULT NULL,
	PRIMARY KEY ("id")
)
;

CREATE TABLE "bd_condicion" (
	"id" INTEGER NOT NULL,
	"condicion" VARCHAR(300) NULL DEFAULT NULL::character varying,
	PRIMARY KEY ("id")
)
;

CREATE TABLE "bd_datos" (
	"id" INTEGER NOT NULL,
	"cedula" VARCHAR(300) NULL DEFAULT NULL,
    "nombre" VARCHAR(300) NULL DEFAULT NULL,
    "apellido" VARCHAR(300) NULL DEFAULT NULL,
    "id_departamento"	  INTEGER NULL DEFAULT NULL,
    "id_condicion"	 INTEGER NULL DEFAULT NULL,
    "id_tipopersonal"	 INTEGER NULL DEFAULT NULL,
    "id_ente" INTEGER NULL DEFAULT NULL,
	PRIMARY KEY ("id")
)
;








